  function openPasscodeDialog(trigger){document.querySelector('[data-nova-passcode-dialog]')?.remove();const backdrop=document.createElement('div');backdrop.className='dialog-backdrop';backdrop.dataset.novaPasscodeDialog='true';backdrop.innerHTML=`<div class="dialog" role="dialog" aria-modal="true" aria-labelledby="nova-passcode-title" aria-describedby="nova-passcode-copy" tabindex="-1"><h2 id="nova-passcode-title">Use passcode instead</h2><p id="nova-passcode-copy">Biometrics failed before any money movement. Enter the prototype passcode to continue this simulated confirmation flow.</p><form data-nova-passcode-form novalidate><div class="field"><label for="nova-demo-passcode">Prototype passcode</label><input id="nova-demo-passcode" class="input nova-passcode-input" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="off" aria-describedby="nova-passcode-hint nova-passcode-error" aria-invalid="false"><div id="nova-passcode-hint" class="nova-passcode-hint">Prototype hint: use <strong>2468</strong> to inspect the success path. No credential is stored.</div><div id="nova-passcode-error" class="nova-passcode-error" role="alert" aria-live="assertive" hidden></div></div><div class="dialog-actions"><button class="btn btn-primary" type="submit">Confirm passcode</button><button class="btn btn-secondary" type="button" data-nova-passcode-cancel>Cancel</button></div></form></div>`;document.body.appendChild(backdrop);const dialog=backdrop.querySelector('.dialog'),form=backdrop.querySelector('[data-nova-passcode-form]'),input=backdrop.querySelector('#nova-demo-passcode'),error=backdrop.querySelector('#nova-passcode-error'),cancel=backdrop.querySelector('[data-nova-passcode-cancel]');const close=()=>{document.removeEventListener('keydown',onKeydown);backdrop.remove();trigger?.focus?.();};const setError=(message)=>{input.setAttribute('aria-invalid','true');error.hidden=false;error.textContent=message;input.focus();input.select();};const clearError=()=>{input.setAttribute('aria-invalid','false');error.hidden=true;error.textContent='';};const onKeydown=(event)=>{if(event.key==='Escape'){event.preventDefault();close();return;}if(event.key!=='Tab')return;const focusable=[...backdrop.querySelectorAll('button,input,[href],[tabindex]:not([tabindex="-1"])')].filter((node)=>!node.disabled),first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}};input.addEventListener('input',clearError);form.addEventListener('submit',(event)=>{event.preventDefault();const value=input.value.trim();if(!value)return setError('Enter the 4-digit prototype passcode.');if(!/^\d{4}$/.test(value))return setError('Use exactly 4 numbers for the prototype passcode.');if(value!==DEMO_PASSCODE)return setError('That prototype passcode does not match. Try again.');clearError();close();location.href='app.html?screen=transfer-success';});cancel.addEventListener('click',close);backdrop.addEventListener('mousedown',(event)=>{if(event.target===backdrop)close();});document.addEventListener('keydown',onKeydown);dialog.focus();requestAnimationFrame(()=>input.focus());}
