  function handleSavingsPreview(event){const button=event.target.closest?.('#save-contribution');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const ui=ensureSavingsUi();if(!ui)return;const raw=ui.input.value.trim(),value=Number(raw);const fail=(message)=>{ui.input.setAttribute('aria-invalid','true');ui.error.textContent=message;ui.error.hidden=false;ui.status.classList.add('is-warning');ui.status.innerHTML=`<strong>Preview not updated</strong>${message}`;ui.status.hidden=false;ui.input.focus();};if(!raw)return fail('Enter a monthly contribution to preview.');if(!Number.isFinite(value))return fail('Enter a valid number for the monthly contribution.');if(value<0)return fail('Monthly contribution cannot be negative. Use €0 to preview a paused contribution.');if(value>MODEL.maxSavingsPreview)return fail(`Monthly contribution cannot exceed ${money(MODEL.maxSavingsPreview)} in this prototype.`);const normalized=Math.round(value*100)/100;ui.input.value=String(normalized);ui.input.removeAttribute('aria-invalid');ui.error.hidden=true;ui.error.textContent='';const result=renderSavingsHorizon(normalized);if(!result)return;ui.status.classList.toggle('is-warning',result.shortfall>0);ui.status.innerHTML=result.shortfall>0?`<strong>Overcommitted by ${money(result.shortfall)}</strong>${money(result.committed)} would be committed including this savings goal, leaving Safe to spend at ${money(result.safe,{signed:true})}. This is a preview only.`:`<strong>Preview updated</strong>${money(result.committed)} committed · ${money(result.safe)} Safe to spend · ${money(MODEL.protectedBuffer)} protected. No money has moved.`;ui.status.hidden=false;}
